.print-format .table-bordered,
.print-format .table-bordered th,
.print-format .table-bordered td {
    border: 1px solid #000 !important;
}

/* Viền ngoài bảng đậm hơn chút cho rõ khung */
.print-format .table-bordered {
    border: 1.5px solid #000 !important;
}

/* === OT Registration V3 — footer === */
.ot-expl-line { margin: 6px 0 12px; white-space: nowrap; overflow: hidden; font-family: "Times New Roman", serif; }
.ot-approval { width: 100%; border-collapse: collapse; border: none; margin-top: 2px; text-align: center; font-family: "Times New Roman", serif; font-size: 11px; }
.ot-approval td { border: none !important; vertical-align: top; padding: 6px; width: 33.33%; }
.ot-approval .st { font-weight: bold; }
.ot-approval .st-vn { font-style: italic; color: #666; font-size: 9px; }
.ot-approval .gap { height: 36px; }
.ot-approval .role { font-weight: bold; }
.ot-approval .role-vn { font-style: italic; color: #666; font-size: 9px; }
.ot-approval .nm { font-weight: bold; margin-top: 4px; }

/* Section headings ("Danh sách đăng ký /List", "Phê duyệt / Approval") */
.print-format .section-break > h4 { font-size: 13px; font-weight: bold; margin: 4px 0 2px; }

.print-format {
      margin-top: 3mm;
      margin-left: 5mm;
      margin-right: 5mm; 
    /* margin-bottom: 25mm;   /* chừa chỗ cho footer "Page X of Y"  */
  }

/* Hide the Repeat Header and Footer page number for this format only */
.page-number { display: none !important; }

/* Browser (HTML) printing, e.g. tablets: fixed A4 paper and margins, no mobile font boosting */
@page { size: A4; margin: 10mm; }
html, body { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }

